// Receive Pinterest OAuth code, extract, return HTML confirmation page.
// In production n8n auto-handles OAuth credential exchange; this node
// is for demo + manual capture.
const params = $input.item.json.query || {};
const code = params.code || 'NO_CODE';
const state = params.state || 'NO_STATE';

const html = `<!DOCTYPE html><html><head><title>Pinterest OAuth Success</title></head>
<body style="font-family:system-ui;max-width:640px;margin:40px auto;padding:24px">
<h1 style="color:#e60023">✅ Pinterest Authorization Captured</h1>
<p>Authorization code received by n8n webhook:</p>
<pre style="background:#f4f4f4;padding:12px;border:1px solid #ddd;word-break:break-all">${code}</pre>
<p>State (CSRF): <code>${state}</code></p>
<p style="color:#666;margin-top:24px">The workflow now has the access token. You can close this tab.</p>
</body></html>`;

return [{
  json: {
    html: html,
    code: code,
    state: state,
    captured_at: new Date().toISOString()
  }
}];

// Pick next ASIN + board key from queue.
const queue = [
  { asin: "B0009X29WK", boardKey: "pets-cat-care" },
  { asin: "B000E28UQU", boardKey: "home-cleaning-essentials" },
  { asin: "B000H3I2JG", boardKey: "tools-hand" }
];
const item = queue[Math.floor(Math.random() * queue.length)];
return [{ json: { ...item, pickedAt: new Date().toISOString() } }];

// Map board key -> Pinterest board ID, build pin payload.
const BOARD_MAP = {
  "pets-cat-care": "1117174320005947890",
  "pets-dog-life": "1117174320005947891",
  "home-cleaning-essentials": "1117174320005947881",
  "tools-hand": "1117174320005947896",
  "tools-power": "1117174320005947895",
  "kitchen-cookware": "1117174320005947884",
  "beauty-skincare": "1117174320005947872"
};
const ASIN_META = {
  "B0009X29WK": { title: "Dr. Elsey's Cat Litter", price: "20.99", rating: "4.7" },
  "B000E28UQU": { title: "O-Cedar Microfiber Mop", price: "21.99", rating: "4.6" },
  "B000H3I2JG": { title: "Stanley FatMax Hand Tools", price: "29.99", rating: "4.8" }
};
const picked = $('Pick ASIN').item.json;
const boardId = BOARD_MAP[picked.boardKey];
if (!boardId) throw new Error(`No board for ${picked.boardKey}`);
const meta = ASIN_META[picked.asin] || { title: picked.asin, price: "19.99", rating: "4.5" };
const affiliateUrl = `https://www.amazon.com/dp/${picked.asin}/?tag=redvibes20-20&linkCode=ogi&th=1`;
const imageUrl = `https://pub-ce32d87fa3e24cf9bdf9bacd8ec03704.r2.dev/pin/${picked.asin}.png`;
const payload = {
  board_id: boardId,
  title: `${meta.title} - $${meta.price} on Amazon`,
  description: `${meta.title} - premium quality at $${meta.price}. ${meta.rating}★ from real buyers. #ad #affiliate #amazonfinds`,
  link: affiliateUrl,
  alt_text: `${meta.title} - $${meta.price} on Amazon - ${meta.rating} stars - #ad #affiliate`,
  media_source: { source_type: "image_url", url: imageUrl }
};
return [{ json: { asin: picked.asin, boardId, boardKey: picked.boardKey, payload } }];

const r = $input.item.json;
return [{ json: {
  ok: true,
  event: "pin_published",
  pin_id: r.id,
  asin: $('Build Pin Payload').item.json.asin,
  board_id: $('Build Pin Payload').item.json.boardId,
  link: r.link || null,
  ts: new Date().toISOString()
}}];

const err = $input.item.json;
return [{ json: {
  ok: false,
  event: "pin_failed",
  error: err.message || JSON.stringify(err),
  asin: $('Build Pin Payload').item.json.asin,
  ts: new Date().toISOString()
}}];
